#include "../../activity/PairAdmission.h"
#include <sodium.h>
#include <iostream>
using namespace private_input::activity;
namespace protocol=private_input::protocol;
void check(bool b){if(!b)throw std::runtime_error("admission check");}
template<class F>void rejects(F f){bool b=false;try{f();}catch(...){b=true;}check(b);}
GroupIdentity identity(){GroupIdentity i;i.device=newId();i.owner=newId();randombytes_buf(i.signingSeed.data(),32);randombytes_buf(i.ownerSeed.data(),32);randombytes_buf(i.exchangeSecret.data(),32);return i;}
int main(){check(sodium_init()>=0);auto owner=identity(),phone=identity(),pc=identity();uint64_t now=unixTime();auto before=initialMembership(owner),request=pairRequest(phone,now);auto prepared=prepareAdmission(before,owner,request,now);auto anchor=anchorOf(before);auto old=anchor.verify(protocol::decodeMembershipJSON(before.dump()));auto next=anchor.verify(protocol::decodeMembershipJSON(prepared.bundle.at("membership").dump()),&old);check(next.statement().version==2&&next.statement().members.size()==2);verifyJoinTemplate(prepared.bundle.at("challenge").at("template"),phone,anchor,request,now);for(const auto&p:prepared.bundle.at("packages").items){bool isPhone=parseId(p.at("recipient").str())==phone.device;check(openGroupKey(p,isPhone?phone:owner,anchor,isPhone?nullptr:&old,isPhone?sha256(canonicalPair(request)):Key{},now)==prepared.localKey);}rejects([&]{prepareAdmission(before,pc,request,now);});rejects([&]{prepareAdmission(before,owner,request,now+601);});auto tampered=request;tampered["member"]["permissions"]=1;rejects([&]{prepareAdmission(before,owner,tampered,now);});tampered=request;tampered["member"]["exchangePublic"]=base64(Data(32,0));rejects([&]{prepareAdmission(before,owner,tampered,now);});rejects([&]{prepareAdmission(prepared.bundle.at("membership"),owner,request,now);});
 // A newly joined non-founder device can sponsor another node without the
 // founder's private key or online presence. All old nodes rotate together.
 auto request2=pairRequest(pc,now);auto second=prepareAdmission(prepared.bundle.at("membership"),phone,request2,now);auto third=anchor.verify(protocol::decodeMembershipJSON(second.bundle.at("membership").dump()),&next);check(third.statement().members.size()==3&&third.statement().issuer==phone.device);verifyJoinTemplate(second.bundle.at("challenge").at("template"),pc,anchor,request2,now);for(const auto&p:second.bundle.at("packages").items){auto id=parseId(p.at("recipient").str());bool fresh=id==pc.device;const auto&i=fresh?pc:(id==phone.device?phone:owner);check(openGroupKey(p,i,anchor,fresh?nullptr:&next,fresh?sha256(canonicalPair(request2)):Key{},now)==second.localKey);}std::cout<<"admission: owner+independent-member, challenge, all-recipient ECDH rotation, forged/expired/duplicate rejection passed\n";
}
